	GetLiveMigrateReceiveStatus(context.Context, *GetLiveMigrateReceiveStatusRequest) (*GetLiveMigrateReceiveStatusResponse, error)
	// Clear a stranded receive session on one node. Destructive and refused
	// unless `force` is set, so the default answer is a report of what would be
