	// issued to it before the row is deleted.
	DeleteNode(context.Context, *DeleteNodeRequest) (*DeleteNodeResponse, error)
	// Summary of node readiness, VM placement, certificate expiry, and
	// replication conflicts. Read-only.
	GetClusterHealth(context.Context, *GetClusterHealthRequest) (*GetClusterHealthResponse, error)
	// Consistent SQLite snapshot of the controller database.
	BackupCluster(context.Context, *BackupClusterRequest) (*BackupClusterResponse, error)
	// Replace the controller database from a snapshot. `confirm` must be true.
	RestoreCluster(context.Context, *RestoreClusterRequest) (*RestoreClusterResponse, error)
	// Certificate rotation
	// DEPRECATED: ships a controller-generated private key over the wire. Use
	// SignNodeCsr, which keeps the node private key on the node. Kept so older
	// node-agents keep renewing until they are upgraded.
	RenewNodeCert(context.Context, *RenewNodeCertRequest) (*RenewNodeCertResponse, error)
	// Bootstrap a node cert/key pair signed by controller sub-CA for fresh installs.
	IssueNodeBootstrapCert(context.Context, *IssueNodeBootstrapCertRequest) (*IssueNodeBootstrapCertResponse, error)
	RotateSubCa(context.Context, *RotateSubCaRequest) (*RotateSubCaResponse, error)
	ReloadTls(context.Context, *ReloadTlsRequest) (*ReloadTlsResponse, error)
	// PKI lifecycle: CSR-based rotation, inventory, revocation, CRL/OCSP.
	// The node generates its own keypair and submits a CSR; the private key
	// never leaves the node.
	SignNodeCsr(context.Context, *SignNodeCsrRequest) (*SignNodeCsrResponse, error)
	// Operator-triggered rotation for one node or the whole cluster.
	RotateNodeCerts(context.Context, *RotateNodeCertsRequest) (*RotateNodeCertsResponse, error)
	ListCertificates(context.Context, *ListCertificatesRequest) (*ListCertificatesResponse, error)
	RevokeCertificate(context.Context, *RevokeCertificateRequest) (*RevokeCertificateResponse, error)
