	DeleteVolumeSnapshot(context.Context, *DeleteVolumeSnapshotRequest) (*DeleteVolumeSnapshotResponse, error)
	RestoreVolume(context.Context, *RestoreVolumeRequest) (*RestoreVolumeResponse, error)
	FlattenVolume(context.Context, *FlattenVolumeRequest) (*FlattenVolumeResponse, error)
	ResizeVolume(context.Context, *ResizeVolumeRequest) (*ResizeVolumeResponse, error)
	// In-place LUKS over an existing plain RBD image (data-destructive; see destroy_data).
	EncryptVolume(context.Context, *EncryptVolumeRequest) (*EncryptVolumeResponse, error)
	CreateSnapshotPolicy(context.Context, *CreateSnapshotPolicyRequest) (*CreateSnapshotPolicyResponse, error)
	GetSnapshotPolicy(context.Context, *GetSnapshotPolicyRequest) (*GetSnapshotPolicyResponse, error)
	ListSnapshotPolicies(context.Context, *ListSnapshotPoliciesRequest) (*ListSnapshotPoliciesResponse, error)
	DeleteSnapshotPolicy(context.Context, *DeleteSnapshotPolicyRequest) (*DeleteSnapshotPolicyResponse, error)
	// DiskLayout resource — per-node declarative disk layout. Implemented on the
	// node via disko; the operator surface uses the plain word "disk". Each
	// DiskLayout targets exactly one node; dangerous requests (those that would
	// touch a device currently backing an active workload) are refused by both
	// the controller pre-flight and the authoritative node-agent re-classifier.
	CreateDiskLayout(context.Context, *CreateDiskLayoutRequest) (*CreateDiskLayoutResponse, error)
	GetDiskLayout(context.Context, *GetDiskLayoutRequest) (*GetDiskLayoutResponse, error)
