	// operators can see SAFE/DANGEROUS before applying.
	ClassifyDiskLayout(context.Context, *ClassifyDiskLayoutRequest) (*ClassifyDiskLayoutResponse, error)
	// ClusterUpdate — flake-pinned kcore / host OS rollouts across nodes.
	CreateClusterUpdate(context.Context, *CreateClusterUpdateRequest) (*CreateClusterUpdateResponse, error)
	GetClusterUpdate(context.Context, *GetClusterUpdateRequest) (*GetClusterUpdateResponse, error)
	ListClusterUpdates(context.Context, *ListClusterUpdatesRequest) (*ListClusterUpdatesResponse, error)
	PlanClusterUpdate(context.Context, *PlanClusterUpdateRequest) (*PlanClusterUpdateResponse, error)
